import * as React from 'react';

export interface ProgressTrackerContextProps {
  currentStep: number;
  orientation: 'horizontal' | 'vertical';
  size: 'small' | 'large';
}

const ProgressTrackerContext = React.createContext<ProgressTrackerContextProps | undefined>(
  undefined
);

export function useProgressTrackerContext(): ProgressTrackerContextProps | undefined {
  return React.useContext(ProgressTrackerContext);
}

export default ProgressTrackerContext;
